ob_start();
?>
<div class="grid gap-5">
    <div class="grid gap-2"><h3 class="text-sm font-semibold">Inventory owner actions</h3><?php foreach ($catalogProjection['owner_actions'] ?? [] as $action): ?><a class="inline-flex min-h-9 items-center gap-2 rounded-md bg-muted px-3 py-2 text-sm font-medium hover:bg-muted/70" href="<?= bx_h((string) $action['href']) ?>"><span class="material-symbols-rounded text-base" aria-hidden="true">open_in_new</span><?= bx_h((string) $action['label']) ?></a><?php endforeach; ?></div>
    <div class="grid gap-3"><h3 class="text-sm font-semibold">Owner sources</h3><?php foreach ($catalogSources as $source): ?><div class="rounded-md bg-muted/40 p-3"><p class="text-sm font-medium"><?= bx_h((string) ($source['service'] ?? 'Inventory service')) ?></p><p class="mt-1 break-all text-xs font-medium"><?= bx_h((string) ($source['status'] ?? 'UNAVAILABLE_DEPENDENCY')) ?></p><?php if (($source['reason'] ?? '') !== ''): ?><p class="mt-2 text-xs leading-5 text-muted-foreground"><?= bx_h((string) $source['reason']) ?></p><?php endif; ?></div><?php endforeach; ?></div>
</div>
<?php
$operationsSectionTools = (string) ob_get_clean();
?>
<div class="grid gap-5" data-operations-catalog-units>
    <div><h2 class="text-base font-semibold">Catalog and unit projections</h2><p class="mt-1 text-sm leading-6 text-muted-foreground">Read-only Inventory UOM definitions and item conversion directions. Authoritative catalog changes remain in Inventory.</p></div>
    <div class="grid gap-3 sm:grid-cols-2">
