    <div class="grid gap-3"><h3 class="text-sm font-semibold">Conversion directions</h3><div class="overflow-x-auto"><table class="w-full min-w-[50rem] text-left text-sm"><thead class="bg-muted/50 text-xs text-muted-foreground"><tr><th class="px-3 py-2.5">From</th><th class="px-3 py-2.5">To stock UOM</th><th class="px-3 py-2.5">Category</th><th class="px-3 py-2.5">Factor</th><th class="px-3 py-2.5">Item reference</th></tr></thead><tbody class="divide-y"><?php if ($catalogConversions === []): ?><tr><td colspan="5" class="px-3 py-8 text-center text-muted-foreground"><?= ($catalogDirectories['uom_conversion_factor']['status'] ?? '') === 'AVAILABLE' ? 'No verified conversion rows are exposed by current items.' : 'UOM conversion records are unavailable from Inventory.' ?></td></tr><?php else: foreach ($catalogConversions as $conversion): ?><tr><td class="px-3 py-2.5 font-medium"><?= bx_h((string) $conversion['from_uom_code']) ?></td><td class="px-3 py-2.5"><?= bx_h((string) $conversion['to_uom_code']) ?></td><td class="px-3 py-2.5"><?= bx_h((string) $conversion['uom_category']) ?></td><td class="px-3 py-2.5 font-mono text-xs"><?= bx_h((string) $conversion['conversion_factor']) ?></td><td class="px-3 py-2.5 font-mono text-xs break-all"><?= bx_h((string) $conversion['item_key']) ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
